<?php require_once __DIR__.'/includes/bootstrap.php';if(is_logged_in())redirect('/dashboard.php');$message='';$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim($_POST['email']??''));if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email address.';else{$s=$pdo->prepare('SELECT id FROM users WHERE email=?');$s->execute([$email]);$u=$s->fetch();$message='If that email is registered, a password reset link has been created.';if($u){$token=bin2hex(random_bytes(32));$hash=hash('sha256',$token);$s=$pdo->prepare('INSERT INTO password_resets(user_id,token_hash,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 30 MINUTE))');$s->execute([$u['id'],$hash]);$_SESSION['dev_reset_link']=BASE_URL.'/reset_password.php?token='.$token;}}}$page_title='Forgot password';require __DIR__.'/includes/header.php'; ?><div class="auth-wrap"><section class="panel form-panel"><h1>Forgot Password</h1><p class="muted">Enter the email address connected to your account.</p><?php foreach($errors as $err): ?><div class="alert error"><?= e($err) ?></div><?php endforeach; ?><?php if($message): ?><div class="alert success"><?= e($message) ?></div><?php if(!empty($_SESSION['dev_reset_link'])): ?><p class="muted">Local development link (email delivery is not configured):</p><p class="reset-link"><a href="<?= e($_SESSION['dev_reset_link']) ?>">Continue to reset password</a></p><?php unset($_SESSION['dev_reset_link']);endif; ?><?php endif; ?><form method="post" data-validate><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label>Email address<input type="email" name="email" required autocomplete="email"></label><button class="button primary" type="submit">Request reset link</button></form><p class="form-foot"><a href="login.php">Back to login</a></p></section></div><?php require __DIR__.'/includes/footer.php'; ?>